def test_parse_reads_the_published_fields_and_never_the_commented_out_ones():
    d = R.parse_detail(PAGE_2721)
    assert d["ad_no"] == "7200906376"
    assert d["location"] == ["منطقة مكة المكرمة", "جدة", "الروضة"]
    assert d["price_text"] == "2,200,000" and d["installment_text"] == "14,391"
    assert d["deal_text"] == "بيع" and d["type_text"] == "شقة"
    assert d["specs"] == ["مساحة 290م", "غرف (6)", "حمام (6)", "غرفة خادمة", "بها مصعد", "بها مسبح", "بها جراج",
                          "موقف خاص", "مكيف هواء"]
    assert d["description"].startswith("مجتمع سدنة") and d["deed_text"].startswith("حي الروضة بمدينة جدة")
    assert d["photos"] and all(p.startswith("https://dashboard.sodasyat.sa/public/storage/photos/") for p in d["photos"])
    assert "1200016192" in PAGE_2721 and "1200016192" not in str(d)          # the FAL licence is commented out
    assert "إسم المعلن" in PAGE_2721 and "إسم المعلن" not in str(d)          # so is the advertiser name


def test_a_field_the_page_comments_out_is_not_published():
    """The page already comments out an advertiser name and a «حاله العقار»; the same markup around
    the deal span must make the deal unpublished, not read through the comment."""
    hidden, n = re.subn(r"(<span>\s*نوع العقار : شقة</span>)", r"<!-- \1 -->", PAGE_2721)
    assert n == 1
    assert R.parse_detail(hidden)["type_text"] is None
    assert R.map_listing("2721", R.parse_detail(hidden))[2] == "type_unmapped"


def test_price_is_exact_and_the_instalment_is_neither_rent_nor_price():
    row, cat, why = R.map_listing("2721", R.parse_detail(PAGE_2721))
    assert why == "" and cat == "residential"
    assert row["ad_number"] == "SDS2721" and row["listing_url"] == "https://sodasyat.sa/single/2721"
    assert row["transaction_type"] == "Buy" and row["price_total"] == 2_200_000
    assert "price_annual" not in row and "rent_period" not in row
    assert row["additional_info"]["monthly_installment_from"] == 14_391
    assert row["additional_info"]["price_raw"] == "2,200,000"


def test_specs_are_tri_state_by_the_sites_own_wording():
    cols, rest = R.specs_to_fields(["مساحة 120.6م", "غرف (4)", "بدون غرفة خادمة", "حمام (3)", "بدون مسبح",
                                    "موقف خاص", "بها مصعد", "بدون غرفة سائق"])
    assert cols == {"area_m2": 120, "_area_raw": "مساحة 120.6م", "bedrooms": 4, "bathrooms": 3,
                    "maid_room": False, "parking": True, "elevator": True, "driver_room": False}
    assert rest == ["بدون مسبح"]
    assert R.specs_to_fields(["تأسيس مصعد"]) == ({}, ["تأسيس مصعد"])     # prepared shaft → NULL


def test_card_negations_fill_what_the_detail_omits_and_the_detail_wins():
    d = {**R.parse_detail(PAGE_2721), "specs": ["مساحة 4891م", "غرف (7)", "غرفة سائق", "تأسيس مصعد"]}
    row = R.map_listing("2734", d, ["جدة الروضه", "بدون مصعد", "بدون غرفة سائق", "بدون مسبح"])[0]
    assert row["elevator"] is False            # card says بدون مصعد, detail only «تأسيس مصعد»
    assert row["driver_room"] is True          # detail names it → detail wins over the card's بدون
    assert row["area_m2"] == 4891 and row["additional_info"]["area_raw"] == "مساحة 4891م"
    silent = R.map_listing("2734", {**d, "specs": ["مساحة 4891م"]}, [])[0]
    assert "elevator" not in silent and "driver_room" not in silent


def test_licence_from_the_h1_and_identity_from_the_path():
    row = R.map_listing("2721", R.parse_detail(PAGE_2721))[0]
    assert row["license_number"] == "7200906376" and row["additional_info"]["ad_no_raw"] == "7200906376"
    d = R.parse_detail(PAGE_2721)
    assert d["facts"]["رقم الترخيص"] == "7200906376"                      # the page labels it
    odd = R.map_listing("2721", {**d, "ad_no": "12345", "facts": {k: v for k, v in d["facts"].items() if k != "رقم الترخيص"}})[0]
    assert odd["license_number"] is None and odd["additional_info"]["ad_no_raw"] == "12345"
    lab = R.map_listing("2721", {**d, "ad_no": "12345"})[0]
    assert lab["license_number"] == "7200906376"                             # labelled fact, h1 odd


