def test_skips_are_named_never_guessed():
    d = R.parse_detail(PAGE_2721)
    assert R.map_listing("2721", {**d, "location": ["منطقة كذا", "قرية مجهولة", "حي"]})[2] == "city_not_in_catalog"
    assert R.map_listing("2721", {**d, "location": []})[2] == "city_not_stated"
    assert R.map_listing("2721", {**d, "deal_text": None})[2] == "no_deal_stated"
    assert R.map_listing("2721", {**d, "type_text": "سيارة"})[2] == "type_unmapped"
    assert R.map_listing("2721", {**d, "description": "مزاد علني"})[2] == "auction"
    assert R.map_listing("2721", {**d, "description": "تم البيع"})[2] == "sold_or_rented"
    assert R.map_listing("2721", {**d, "ad_no": None})[2] == "not_a_listing_page"
    rent = R.map_listing("2721", {**d, "deal_text": "إيجار"})[0]
    assert rent["transaction_type"] == "Rent" and rent["rent_period"] is None and rent["price_annual"] == 2_200_000


def test_the_facts_block_reaches_its_columns_and_a_person_reaches_none():
    row = R.map_listing("2721", R.parse_detail(PAGE_2721))[0]
    assert row["property_age"] == 0                                    # «عمر العقار : جديد»
    assert row["street_width_m"] is None and row["direction"] is None  # «عرض الشارع : - م», no facade
    assert row["electricity"] is True and row["water_supply"] is True  # «خدمات : كهرباء , مياه»
    assert "sanitation" not in row                                     # not named → NULL
    assert row["price_per_meter"] == 7587 and row["price_total"] == 2_200_000   # both as printed
    assert row["additional_info"]["price_per_meter_raw"] == "7587 ريال" and row["additional_info"]["age_raw"] == "جديد"
    assert "[اسم شخص]" in PAGE_2721 and "[رقم جوال]" in PAGE_2721
    assert "[اسم شخص]" not in str(row) and "[رقم جوال]" not in str(row) and "مسؤول" not in str(row)
    villa = R.map_listing("2730", R.parse_detail(" ".join([HEADER_2721, GRID_2721, FACTS_2730, DESC_2721])))[0]
    assert villa["street_width_m"] == 15 and villa["direction"] == "شرق"   # «عرض الشارع : 15 م», «واجهة العقار : شرقية»
    assert villa["electricity"] is True and villa["water_supply"] is True and villa["property_age"] == 0
    two = R.map_listing("2734", R.parse_detail(" ".join([HEADER_2721, GRID_2721, FACTS_2721, FACADE_2734, DESC_2721])))[0]
    assert two["direction"] is None                                    # «غربية - شرقية» = two facades
    old = R.map_listing("2721", {**R.parse_detail(PAGE_2721), "facts": {"عمر العقار": "أكثر من 10", "خدمات": ""}})[0]
    assert old["property_age"] is None and "electricity" not in old   # open bound → NULL; silent → NULL


def test_a_wafi_project_is_off_plan_not_an_available_unit():
    d = R.parse_detail(" ".join([HEADER_2721, GRID_2721, FACTS_2721, FACADE_2734, DESC_2734]))
    assert d["description"].startswith("سدنة تاون هاوس") and "تابع لنظام وافي" in d["description"]
    assert R.map_listing("2734", d)[2] == "off_plan"
    assert R.map_listing("2734", {**d, "description": "المشروع تحت الإنشاء (بيع على الخارطة)"})[2] == "off_plan"
    assert R.map_listing("2734", {**d, "description": "شقة جاهزة للسكن تقريبا 290م"})[2] == ""   # «تقريبا» is not «قريبا»


